package com.smokedevilhider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SmokeDevilHiderTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SmokeDevilHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.smokedevilhider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("smokedevilhider")
public interface SmokeDevilHiderConfig extends Config
{
	@ConfigItem(
		keyName = "hideProjectile",
		name = "Smoke projectile",
		description = "Hide the smoke projectile flying at you.",
		position = 1
	)
	default boolean hideProjectile()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hidePlayerSmoke",
		name = "Smoke on player",
		description = "Hide the smoke puff that appears on you when hit.",
		position = 2
	)
	default boolean hidePlayerSmoke()
	{
		return true;
	}
}

package com.smokedevilhider;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Smoke Devil Effects Hider",
	description = "Hides the smoke attack effects of Smoke devils to reduce eye strain",
	tags = {"smoke", "devil", "nuclear", "thermonuclear", "slayer", "hide", "effects", "eye", "strain"}
)
public class SmokeDevilHiderPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private SmokeDevilHiderConfig config;

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		// Smoke projectile: end it in the past so the client culls it entirely
		// (ending it on the current cycle freezes its last frame on you instead).
		// Purely visual - the hit is already resolved server-side.
		if (config.hideProjectile())
		{
			final int endCycle = client.getGameCycle() - 1;
			for (Projectile p : client.getProjectiles())
			{
				if (p != null && p.getId() == SpotanimID.SMOKE_DEVIL_SMOKE_PROJ)
				{
					p.setEndCycle(endCycle);
				}
			}
		}

		// Smoke puff on the player when hit: strip the spotanim off the player.
		if (config.hidePlayerSmoke())
		{
			removeSpotAnim(client.getLocalPlayer(), SpotanimID.SMOKE_DEVIL_SMOKE_PLAYER_SPOTANIM);
		}
	}

	private static void removeSpotAnim(Actor actor, int spotAnimId)
	{
		if (actor == null)
		{
			return;
		}
		final Iterable<ActorSpotAnim> spotAnims = actor.getSpotAnims();
		if (spotAnims == null)
		{
			return;
		}

		List<Integer> removeSlots = null;
		for (ActorSpotAnim sa : spotAnims)
		{
			if (sa.getId() == spotAnimId)
			{
				if (removeSlots == null)
				{
					removeSlots = new ArrayList<>();
				}
				removeSlots.add((int) sa.getHash());
			}
		}

		if (removeSlots != null)
		{
			for (int slot : removeSlots)
			{
				actor.removeSpotAnim(slot);
			}
		}
	}

	@Provides
	SmokeDevilHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SmokeDevilHiderConfig.class);
	}
}
